def _convert_token(self, token):
        """Convert token fields from camel case.

        :param dict token: An authentication token.
        :rtype: dict
        """
        return {
            'id': token['id'],
            'expires': token['expires'],
            'expires_at': token['expires_at'],
            'issued_at': token['issued_at'],
            'project': {
                'id': token['project']['id'],
                'name': token['project']['name'],
                'domain': {
                    'id': token['project']['domain']['id'],
                    'name': token['project']['domain']['name'],
                },
            },
            'user': {
                'id': token['user']['id'],
                'name': token['user']['name'],
                'domain': {
                    'id': token['user']['domain']['id'],
                    'name': token['user']['domain']['name'],
                },
            },
            'roles': [
                {
                    'id': role['id'],
                    'name': role['name'],
                } for role in token['roles']
            ],
        }

